@startuml

class WebPortal {
  + versionNumber : string
  + urlAddress : string
}

class Building {
  + id : string
  + name : string
  + energyClass : string
  + address : string
  + yearOfConstruction : int
}

class AdditionalEntry {
  + name : string
  + value : string
  + unit : string
  + isPublic : boolean
}

class Image {
  + fileName : string
}

class User {
  + userName : string
  + emailAddress : string
  + password : string
}

class Administrator extends User {
  + idCardNumber : string
}

class Comment {
  + text : string
}

WebPortal "1" -- "*" Building
WebPortal "1" -- "*" User
Building "1" *-- "*" AdditionalEntry
Building "1" *-- "*" Image
Building "1" -- "0..1" Image : profile photo
User "1" -- "*" Building : owner
User "1" -- "*" Comment : writes
Building "1" -- "*" Comment : has
User "0..*" -- "0..*" Building : searches

@enduml

